def eval_expression(expr: str) -> float:
    """
    Evaluate a mathematical expression string with support for:
    - Addition (+), Subtraction (-), Multiplication (*), Division (/)
    - Parentheses for grouping
    - Negative numbers
    - Proper order of operations (PEMDAS/BODMAS)

    Raises:
        ZeroDivisionError: If division by zero is attempted

    Example:
        >>> eval_expression("3 + 4 * (2 - 1)")
        7
    """
    # We'll use a recursive descent parser to handle order of properly.
    # The grammar:
    #   expression = term (('+' | '-') term)*
    #   term = factor (('*' | '/') factor)*
    #   factor = number | '(' expression ')' | ('+' | '-') factor

    # First, tokenize the expression
    def tokenize(s: str):
        tokens = []
        i = 0
        while i < len(s):
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch in '+-*/()':
                tokens.append(ch)
                i += 1
            elif ch.isdigit() or ch == '.':
                j = i
                while j < len(s) and (s[j].isdigit() or s[j] == '.'):
                    j += 1
                tokens.append(s[i:j])
                i = j
            else:
                raise ValueError(f"Unexpected character: {ch}")
        return tokens

    tokens = tokenize(expr)
    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_expression():
        """expression = term (('+' | '-') term)*"""
        result = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                result = result + right
            else:
                result = result - right
        return result

    def parse_term():
        """term = factor (('*' | '/') factor)*"""
        result = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                result = result * right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                result = result / right
        return result

    def parse_factor():
        """factor = number | '(' expression ')' | ('+' | '-') factor"""
        token = peek()
        if token is None:
            raise ValueError("Unexpected end of expression")

        if token == '(':
            consume()  # consume '('
            result = parse_expression()
            if peek() != ')':
                raise ValueError("Expected ')'")
            consume()  # consume ')'
            return result

        if token == '+':
            consume()
            return parse_factor()

        if token == '-':
            consume()
            return -parse_factor()

        # Must be a number
        if token.isdigit() or (token[0] == '.' and len(token) > 1):
            num_str = consume()
            try:
                return float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")
        elif token[0].isdigit():
            num_str = consume()
            try:
                return float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")
        else:
            raise ValueError(f"Unexpected token: {token}")

    result = parse_expression()

    # Ensure we consumed all tokens
    if pos != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos]}")

    # Return int if result is a whole number, for cleanliness
    if isinstance(result, float) and result == int(result) and abs(result) < 10**15:
        return int(result)
    return result
